<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$q=trim((string)($_GET['q']??$_POST['customer']??''));$rows=[];if($q!==''){$s=db()->prepare('SELECT * FROM customer WHERE customer_firstname LIKE ? OR customer_lastname LIKE ? OR customer_TCno LIKE ? OR customer_email LIKE ? ORDER BY customer_firstname');$like="%$q%";$s->execute([$like,$like,$like,$like]);$rows=$s->fetchAll();}page_header('Search','search');?>
<div class="page-head"><h1>Search Customers</h1></div><form method="get" class="toolbar"><input name="q" value="<?=e($q)?>" placeholder="Customer name, TC no or email"><button class="btn primary">Search</button></form><section class="card table-wrap"><table><thead><tr><th>Customer</th><th>TC No</th><th>Telephone</th><th>Email</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['customer_firstname'].' '.$r['customer_lastname'])?></td><td><?=e($r['customer_TCno'])?></td><td><?=e($r['customer_telephone'])?></td><td><?=e($r['customer_email'])?></td><td><a href="customer_edit.php?id=<?=$r['customer_id']?>">Open</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty"><?=$q?'No matching customers.':'Enter a search term.'?></td></tr><?php endif;?></tbody></table></section><?php page_footer();?>
